; c01_csr_branch -- EXEC_CSR one-byte forms and an unconditional branch
; Layer-1 conformance test (generated by conformance/make_conformance.py: edit that, not this file).
; Checks: opcode / arg split of the instruction byte; CsrOneByteDesc (operation, address) and its byte order; the immediate byte; BranchDesc target
; Results go to the result CSRs RES + n (conf_defs.inc); the last write is RES_DONE = 0xA5. Expected values: c01_csr_branch.expected.csv
.include "conf_defs.inc"
.main
    EXEC_CSR WRITE8 RES + 0, 0x5A              ; a plain write
    EXEC_CSR WRITE8 RES + 1, 0xF0
    EXEC_CSR SET8   RES + 1, 0x0F              ; read-modify-write OR:  0xF0 | 0x0F
    EXEC_CSR WRITE8 RES + 2, 0xFF
    EXEC_CSR CLR8   RES + 2, 0x3C              ; read-modify-write AND NOT:  0xFF & ~0x3C
    JMP over                                   ; the next write must be skipped
    EXEC_CSR WRITE8 RES + 3, 0xBD
over:
    EXEC_CSR WRITE8 RES + 4, 0x0D
    EXEC_CSR WRITE8 RES_DONE, 0xA5          ; the last write: everything above is there
done:
    JMP done
